},{"Ar":"$y_m=(1+7)/2$","En":"$y_m=(1+7)/2$"},{"Ar":"منتصف المسافة يبعد ثلاث وحدات عن كل مستقيم، ويقع عند y=4.","En":"The halfway line is three units from each, at y=4."}],"Result":{"Ar":"$y=4$","En":"$y=4$"},"CommonError":{"Ar":"احسب المتوسط لا نصف الفرق وحده.","En":"Use the average, not just half the difference."},"FormulaLatex":"y_m=(y_1+y_2)/2","Substitution":{"Ar":"$y=4$","En":"$y=4$"},"Verification":{"Ar":"$|4-1|=|4-7|=3$","En":"$|4-1|=|4-7|=3$"}},"Distractors":[{"ErrorType":"","Reason":null,"Order":1},{"ErrorType":"incorrect-option","Reason":{"Ar":"y=3 يبعد وحدتين عن الأول وأربعاً عن الثاني.","En":"y=3 is two units from the first and four from the second."},"Order":2},{"ErrorType":"incorrect-option","Reason":{"Ar":"x=4 مستقيم رأسي وليس موازياً للمستقيمين.","En":"x=4 is vertical, not parallel to the given lines."},"Order":3},{"ErrorType":"incorrect-option","Reason":{"Ar":"y=6 يبعد خمس وحدات عن الأول ووحدة عن الثاني.","En":"y=6 is five units from the first and one from the second."},"Order":4}]}$mw$,$mw$المستقيم المتوسط بين مستقيمين أفقيين متوازيين يقع عند متوسط ارتفاعيهما.

$y_m=(y_1+y_2)/2$

